"""Regenerate src/tokport/_models.py from the live catalog: python scripts/generate_models.py"""

import json
import pathlib
import urllib.request

URL = "https://tokport.io/api/models"
OUT = pathlib.Path(__file__).resolve().parent.parent / "src" / "tokport" / "_models.py"

req = urllib.request.Request(URL, headers={"user-agent": "tokport-python-codegen"})
with urllib.request.urlopen(req, timeout=30) as res:
    models = json.load(res)["models"]
models = sorted((m for m in models if m["status"] == "active"), key=lambda m: (m["modality"], m["id"]))

lines = [
    "# Generated by scripts/generate_models.py from https://tokport.io/api/models. Do not edit.",
    "from typing import Literal",
    "",
    "ModelId = Literal[",
    *(f'    "{m["id"]}",' for m in models),
    "]",
    '"""Model ids live when this release was built. Any newer id from https://tokport.io/models works too."""',
    "",
    "MODEL_MODALITY: dict[str, str] = {",
    *(f'    "{m["id"]}": "{m["modality"]}",' for m in models),
    "}",
    "",
]
OUT.write_text("\n".join(lines))
print(f"wrote {len(models)} models to {OUT}")
